{"CommandLine":"$bytes = [System.IO.File]::ReadAllBytes("C:\Program Files\Allen & Heath\SQ MixPad 1.6.1\SQ MixPad.exe")
$pattern = [System.Text.Encoding]::BigEndianUnicode.GetBytes("SQ5.DAT")
for ($i = 0; $i -lt $bytes.Length - $pattern.Length; $i++) {
    if ($bytes[$i] -eq 0 -and $bytes[$i+1] -eq 0x53 -and $bytes[$i+2] -eq 0 -and $bytes[$i+3] -eq 0x51 -and $bytes[$i+4] -eq 0 -and $bytes[$i+5] -eq 0x35) {
        $match = $true
        for ($j = 0; $j -lt $pattern.Length; $j++) {
            if ($bytes[$i+$j] -ne $pattern[$j]) { $match = $false; break }
        }
        if ($match) { Write-Host "Found UTF-16BE SQ5.DAT at $i" }
    }
}","WaitMsBeforeAsync":8000,"toolSummary":"Locate SQ5.DAT in Qt resources inside SQ MixPad.exe"}
